&= \dfrac{1}{2}\left(\sum_{k = 0}^{2024} e^{ki\theta} + \sum_{k = 0}^{2024} e^{-ki\theta}\right) 
&= \dfrac{1}{2}\left(\dfrac{1-e^{2025i\theta}}{1-e^{i\theta}} + \dfrac{1-e^{-2025i\theta}}{1-e^{-i\theta}}\right)
\end{align*}
